/**
 * The scheduling tools a booking would land in, as the Schedule tab shows them.
 *
 * Nothing here connects to anything. The demo takes no bookings — this is the
 * pitch for what the same receptionist does once a business signs up, and the
 * copy around it has to keep saying so.
 *
 * The glyphs are Simple Icons path data, which is CC0, copied in rather than
 * imported so the bundle carries ten paths instead of three thousand. The marks
 * themselves belong to their owners and are used here only to name the product
 * they stand for. Microsoft withdrew theirs from Simple Icons, so Outlook is
 * drawn as the Microsoft squares instead of a copied path. The restaurant
 * reservation systems (OpenTable, Resy, Tock, SevenRooms, Toast) were never in
 * Simple Icons at all, and a logo redrawn from memory is worse than none, so
 * they get a plain initial on their brand colour: it names the product without
 * pretending to be its mark.
 *
 * Pure data, like lib/use-cases.ts — a client component imports it, so no node
 * imports.
 */

export type IntegrationGroup = "tables" | "calendar" | "booking" | "video";

export type Integration = {
  id: string;
  name: string;
  group: IntegrationGroup;
  /** Brand colour, used for the glyph. */
  hex: string;
  /**
   * A 24x24 path, "microsoft" for the four squares drawn in the component, or
   * "monogram" for an initial on the brand colour where no free glyph exists.
   */
  path: string;
};

