/**
 * Which groups a business is shown, in order. A restaurant leads with the
 * reservation systems and loses video visits, which nobody books a table for;
 * everyone else never sees OpenTable. `booking` is businessNouns().booking.
 */
export function integrationGroupsFor(booking: string): IntegrationGroup[] {
  return booking === "table"
    ? ["tables", "calendar", "booking"]
    : ["calendar", "booking", "video"];
}
